// Client receives GUIFactory and uses its products

// Version A
function createFactory(platform: string) {
  if (platform === 'win') return new WinFactory()
  if (platform === 'mac') return new MacFactory()
  return new DefaultFactory()
}
const factory = createFactory(config.platform)
const button = factory.createButton()

// Version B
class FactoryRegistry {
  private map = new Map<string, GUIFactory>()
  register(key: string, factory: GUIFactory) { this.map.set(key, factory) }
  get(key: string) { return this.map.get(key) }
}
// registry populated at startup and injected into clients
